    public static List<DhcpScapyMessage> parseAll(List<byte[]> payloads) {
        List<DhcpScapyMessage> results = new ArrayList<>();
        for (byte[] p : payloads) results.add(parse(p));
        return results;
    }

    public static String hexDump(byte[] data) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < data.length; i += 16) {
            sb.append(String.format("%04x  ", i));
            StringBuilder asc = new StringBuilder();
            for (int j = i; j < Math.min(i + 16, data.length); j++) {
                sb.append(String.format("%02x ", data[j]));
                asc.append(data[j] >= 32 && data[j] < 127 ? (char) data[j] : '.');
            }
            sb.append(" ").append(asc).append("\n");
        }
        return sb.toString();
    }
